export function unaryEncode(text) {
    const bits = [...text].map(c => c.charCodeAt(0).toString(2).padStart(7, '0')).join('');
    const groups = bits.match(/0+|1+/g) || [];
    return groups.map(g => (g[0] === '1' ? '0 ' : '00 ') + '0'.repeat(g.length)).join(' ');
}
